import * as T from './three.module.js';
import {WolfRig,WOLF_KEY,WOLF_ACTIONS,validateWolfProject} from './wolf-rig.mjs?v=points-1';
import {CHARACTERS} from './character-profiles.mjs';
import {addPointView,jointPositions,fitWolfPoints} from './wolf-point-controls.mjs?v=1';
const $=id=>document.getElementById(id);$('motionControls').disabled=true;$('status').textContent='수정한 늑대 모델을 여는 중입니다.';document.querySelector('header span').textContent='점을 끌어 위치를 정하세요. 네 화면이 함께 바뀝니다.';
$('character').replaceChildren(...CHARACTERS.map(c=>new Option(c.label,c.id)),new Option('몬스터 · 잿빛 늑대','wolf'));$('character').value='wolf';$('character').onchange=()=>{const url=new URL(location.href);url.searchParams.set('character',$('character').value);location.href=url;};$('labLink').textContent='게임에서 확인';$('labLink').href='index.html';$('labLink').target='_blank';document.querySelector('.movement-settings').hidden=true;document.querySelector('.foot-buttons').style.display='none';['x','y','z'].forEach(k=>{const input=$(k);input.parentElement.firstChild.textContent=({x:'X · 좌우',y:'Y · 높이',z:'Z · 앞뒤'})[k];input.min=-10;input.max=10;input.step=.01;});
const row=document.createElement('div');row.className='row';for(const [id,label]of [['addKey','현재 자세 키 저장'],['deleteKey','키 삭제'],['undoWolf','실행 취소'],['redoWolf','다시 실행'],['resetJoint','선택 관절 초기화']]){const b=document.createElement('button');b.id=id;b.textContent=label;row.append(b);}$('motionControls').insertBefore(row,$('status'));const note=document.createElement('p');note.className='hint';note.textContent='점을 끌거나 XYZ 좌표로 자세를 만드세요. Shift로 여러 점을 선택하고 빈 곳을 드래그해 영역을 선택할 수 있습니다. 뼈 길이는 유지됩니다. 같은 브라우저·같은 주소의 게임에 적용됩니다. 파일 저장으로 동작을 따로 보관할 수 있습니다.';$('motionControls').append(note);
let rig,project,index=0,frame=0,playing=false,selected=-1,undo=[],redo=[],dragging=false,views=[],markers=[],keyDragBefore;let selection=[];const scene=new T.Scene();scene.background=new T.Color(0x263842);scene.add(new T.HemisphereLight(0xf2f6ff,0x535060,2));const light=new T.DirectionalLight(0xffead8,2.5);light.position.set(3,5,4);scene.add(light);scene.add(new T.GridHelper(6,24,0x647f88,0x354a55));const current=()=>project.actions[index];
function status(s){$('status').textContent=s;}
function snap(){return structuredClone(project);}
function checkpoint(p=snap()){undo.push(p);if(undo.length>60)undo.shift();redo=[];}
function persist(message='늑대 동작을 저장했습니다. 게임에 적용됩니다.'){try{validateWolfProject(project,rig);localStorage.setItem(WOLF_KEY,JSON.stringify(project));status(message);return true;}catch(e){status('저장하지 못했습니다. '+e.message);return false;}}
function rotations(){return rig.sample(project,current().id,frame/current().fps);}
function pose(){rig.apply(rotations());updateHandles();}
function ensureKey(){const a=current(),f=Math.round(frame);let k=a.keys.find(k=>k.frame===f);if(!k){const r=rotations();k={frame:f,rotations:[...r],translations:r.translations};a.keys.push(k);a.keys.sort((a,b)=>a.frame-b.frame);}return k;}
function loopSync(k){const a=current();if(a.loop&&(k.frame===0||k.frame===a.frames-1)){const target=a.keys.find(x=>x.frame===(k.frame===0?a.frames-1:0));target.rotations=structuredClone(k.rotations);if(k.translations)target.translations=structuredClone(k.translations);else delete target.translations;}}
function select(i){selection=i>=0?[i]:[];selected=i;sync();}
function editResult(result){const key=ensureKey();key.rotations=[...result];key.translations=result.translations;loopSync(key);pose();sync();}
function sync(){const a=current();$('timelineContent').style.setProperty('--frame-count',a.frames);$('timelineContent').style.setProperty('--timeline-width',(a.frames*48-4)+'px');$('action').value=index;$('joint').value=selected;$('frames').value=a.frames;$('fps').value=a.fps;$('loopMotion').checked=a.loop;$('scrub').max=a.frames-1;$('scrub').value=frame;$('play').textContent=playing?'⏸':'▶';$('play').setAttribute('aria-label',playing?'일시정지':'재생');$('undoWolf').disabled=!undo.length;$('redoWolf').disabled=!redo.length;const e=selected>=0?jointPositions(rig)[selected]:null;['x','y','z'].forEach(k=>{$(k).disabled=!e;$(k).value=e?e[k].toFixed(3):'';});$('timeline').replaceChildren(...Array.from({length:a.frames},(_,i)=>{const b=document.createElement('button');b.textContent=(a.keys.some(k=>k.frame===i)?'◆ ':'')+(i+1);b.className=(a.keys.some(k=>k.frame===i)?'key ':'')+(i===Math.round(frame)?'selected':'');b.onclick=()=>{playing=false;frame=i;pose();sync();};return b;}));}
function updateHandles(){rig.group.updateMatrixWorld(true);}
function createViews(){for(const [title,dir]of [['앞',[0,.75,6]],['옆',[6,.75,0]],['위',[0,7,.001]],['쿼터뷰',[5,4,6]]])views.push(addPointView($('views'),title,dir,scene,rig,{stop:()=>{playing=false;sync();},round:()=>{frame=Math.floor(frame);pose();},handles:()=>$('handles').checked,selection:()=>selection,select:ids=>{selection=ids;selected=ids.at(-1)??-1;sync();},sample:rotations,checkpoint,change:editResult,save:persist}));}
for(const k of ['x','y','z'])$(k).onchange=()=>{if(selected<0)return;const values=['x','y','z'].map(k=>Number($(k).value));if(!values.every(v=>Number.isFinite(v)&&Math.abs(v)<=10)){sync();return;}playing=false;frame=Math.floor(frame);checkpoint();editResult(fitWolfPoints(rig,rotations(),[[selected,new T.Vector3(...values)]]));persist();};
$('joint').onchange=()=>select(Number($('joint').value));$('action').onchange=()=>{index=Number($('action').value);frame=0;playing=false;pose();sync();};$('play').onclick=()=>{playing=!playing;sync();};$('scrub').oninput=()=>{playing=false;frame=Number($('scrub').value);pose();sync();};$('previous').onclick=()=>{playing=false;frame=[...current().keys].reverse().find(k=>k.frame<frame)?.frame??0;pose();sync();};$('next').onclick=()=>{playing=false;frame=current().keys.find(k=>k.frame>frame)?.frame??current().frames-1;pose();sync();};$('addKey').onclick=()=>{playing=false;frame=Math.round(frame);checkpoint();loopSync(ensureKey());persist();sync();};$('deleteKey').onclick=()=>{const f=Math.round(frame);if(f===0||f===current().frames-1){status('첫 프레임과 마지막 프레임은 유지합니다.');return;}checkpoint();current().keys=current().keys.filter(k=>k.frame!==f);persist();pose();sync();};$('resetJoint').onclick=()=>{if(selected<0)return;playing=false;frame=Math.round(frame);checkpoint();const k=ensureKey();k.rotations[selected]=[0,0,0,1];if(k.translations)k.translations[selected]=[0,0,0];loopSync(k);persist();pose();sync();};
$('undoWolf').onclick=()=>{if(!undo.length)return;playing=false;redo.push(snap());project=undo.pop();frame=Math.min(frame,current().frames-1);persist();pose();sync();};$('redoWolf').onclick=()=>{if(!redo.length)return;playing=false;undo.push(snap());project=redo.pop();frame=Math.min(frame,current().frames-1);persist();pose();sync();};$('loopMotion').onchange=()=>{checkpoint();current().loop=$('loopMotion').checked;loopSync(current().keys[0]);persist();pose();sync();};$('fps').onchange=()=>{const n=Number($('fps').value);if(n<1||n>60||!Number.isFinite(n)){sync();return;}checkpoint();current().fps=n;persist();sync();};$('frames').onchange=()=>{const n=Number($('frames').value);if(!Number.isInteger(n)||n<2||n>240){sync();return;}checkpoint();const a=current(),old=a.frames-1,map=new Map();for(const k of a.keys){k.frame=Math.round(k.frame/old*(n-1));map.set(k.frame,k);}a.frames=n;a.keys=[...map.values()].sort((a,b)=>a.frame-b.frame);frame=Math.min(frame,n-1);persist();pose();sync();};$('handles').onchange=()=>{updateHandles();select(selected);};$('saveMotion').onclick=()=>persist();
$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(project,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='ordinary-mage-wolf-motions.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('import').onchange=async()=>{try{const f=$('import').files[0];if(!f)return;if(f.size>5e6)throw Error('5MB 이하의 파일을 선택하세요.');const next=validateWolfProject(JSON.parse(await f.text()),rig);checkpoint();project=next;frame=0;playing=false;persist();pose();sync();}catch(e){status('불러오지 못했습니다. '+e.message);}finally{$('import').value='';}};
window.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();persist();}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'&&!['INPUT','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$(e.shiftKey?'redoWolf':'undoWolf').click();}});
try{rig=await WolfRig.load();scene.add(rig.group);try{const raw=localStorage.getItem(WOLF_KEY);project=raw?validateWolfProject(JSON.parse(raw),rig):structuredClone(rig.defaults);}catch(e){project=structuredClone(rig.defaults);status('저장된 동작을 읽지 못해 기본 동작을 열었습니다. '+e.message);}createViews();$('joint').replaceChildren(new Option('선택 없음',-1),...rig.bones.map((b,i)=>new Option(b.name,i)));$('action').replaceChildren(...project.actions.map((a,i)=>new Option(a.name,i)));$('motionControls').disabled=false;pose();sync();status('수정한 늑대 리깅 · 관절 '+rig.bones.length+'개 · 동작 6개');let prev=performance.now();function tick(now){requestAnimationFrame(tick);const dt=Math.min(.05,(now-prev)/1000);prev=now;if(playing&&!dragging){frame+=dt*current().fps;if(frame>current().frames-1){if(current().loop)frame%=current().frames-1;else{frame=current().frames-1;playing=false;sync();}}pose();$('scrub').value=frame;for(const [i,b]of [...$('timeline').children].entries())b.classList.toggle('selected',i===Math.round(frame));}for(const v of views)v.draw();}requestAnimationFrame(tick);window.wolfMotionDebug={state:()=>({ready:true,bones:rig.bones.length,frame,action:current().id,project:structuredClone(project),selection:[...selection],positions:jointPositions(rig).map(p=>p.toArray()),rotations:rig.bones.map(b=>b.quaternion.toArray())}),select,rig,views};}catch(e){status('늑대를 불러오지 못했습니다. '+e.message);}
